import Redis from 'ioredis';
import { ProductService } from './product.service';

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');
const productService = new ProductService();
const CART_TTL = 60 * 60 * 24 * 7; // 7 gün

interface CartItem {
  productId: string;
  quantity: number;
  name: string;
  price: number;
  image?: string;
}

export class CartService {
  private getCartKey(userId: string) {
    return `cart:${userId}`;
  }

  async getCart(userId: string): Promise<CartItem[]> {
    const cart = await redis.hgetall(this.getCartKey(userId));
    return Object.values(cart).map((item) => JSON.parse(item));
  }

  async addItem(userId: string, productId: string, quantity: number = 1) {
    const product = await productService.getById(productId);
    if (!product) throw new Error('Ürün bulunamadı');
    if (product.stock < quantity) throw new Error('Yetersiz stok');

    const key = this.getCartKey(userId);
    const existing = await redis.hget(key, productId);

    let item: CartItem;
    if (existing) {
      item = JSON.parse(existing);
      item.quantity += quantity;
    } else {
      item = {
        productId: product.id,
        quantity,
        name: product.name,
        price: Number(product.price),
        image: product.images[0],
      };
    }

    await redis.hset(key, productId, JSON.stringify(item));
    await redis.expire(key, CART_TTL);

    return this.getCart(userId);
  }

  async removeItem(userId: string, productId: string) {
    await redis.hdel(this.getCartKey(userId), productId);
    return this.getCart(userId);
  }

  async updateQuantity(userId: string, productId: string, quantity: number) {
    if (quantity <= 0) return this.removeItem(userId, productId);

    const key = this.getCartKey(userId);
    const existing = await redis.hget(key, productId);
    if (!existing) throw new Error('Ürün sepette bulunamadı');

    const item: CartItem = JSON.parse(existing);
    item.quantity = quantity;

    await redis.hset(key, productId, JSON.stringify(item));
    await redis.expire(key, CART_TTL);

    return this.getCart(userId);
  }

  async clearCart(userId: string) {
    await redis.del(this.getCartKey(userId));
  }

  async getCartTotal(userId: string): Promise<number> {
    const items = await this.getCart(userId);
    return items.reduce((total, item) => total + item.price * item.quantity, 0);
  }
}

