// src/services/order.service.ts
import { PrismaClient, OrderStatus } from '@prisma/client';
import { AppError } from '../middleware/error-handler';

const prisma = new PrismaClient();

// Geçerli durum geçişleri
const VALID_TRANSITIONS: Record<OrderStatus, OrderStatus[]> = {
  PENDING: ['PAID', 'CANCELLED'],
  PAID: ['PROCESSING', 'REFUNDED'],
  PROCESSING: ['SHIPPED', 'REFUNDED'],
  SHIPPED: ['DELIVERED'],
  DELIVERED: ['REFUNDED'],
  CANCELLED: [],
  REFUNDED: [],
};

export class OrderService {
  async getUserOrders(userId: string, page: number = 1, limit: number = 10) {
    const [orders, total] = await Promise.all([
      prisma.order.findMany({
        where: { userId },
        include: {
          items: { include: { product: { select: { name: true, images: true } } } },
        },
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      prisma.order.count({ where: { userId } }),
    ]);

    return { orders, meta: { page, limit, total, totalPages: Math.ceil(total / limit) } };
  }

  async updateStatus(orderId: string, newStatus: OrderStatus) {
    const order = await prisma.order.findUnique({ where: { id: orderId } });
    if (!order) throw new AppError('Sipariş bulunamadı', 404);

    const allowedTransitions = VALID_TRANSITIONS[order.status];
    if (!allowedTransitions.includes(newStatus)) {
      throw new AppError(
        `Sipariş durumu ${order.status} iken ${newStatus} olarak güncellenemez`,
        400
      );
    }

    return prisma.order.update({
      where: { id: orderId },
      data: { status: newStatus },
    });
  }
}

// src/services/payment.service.ts - refund metodu
async refundOrder(orderId: string) {
  const order = await prisma.order.findUnique({
    where: { id: orderId },
    include: { items: true },
  });

  if (!order) throw new AppError('Sipariş bulunamadı', 404);
  if (!order.stripePaymentId) throw new AppError('Ödeme bilgisi bulunamadı', 400);
  if (order.status === 'REFUNDED') throw new AppError('Sipariş zaten iade edildi', 400);

  // Stripe refund
  const refund = await stripe.refunds.create({
    payment_intent: order.stripePaymentId,
  });

  // Transaction: durum güncelle + stok geri ekle
  await prisma.$transaction(async (tx) => {
    await tx.order.update({
      where: { id: orderId },
      data: { status: 'REFUNDED' },
    });

    for (const item of order.items) {
      await tx.product.update({
        where: { id: item.productId },
        data: { stock: { increment: item.quantity } },
      });
    }
  });

  return { refundId: refund.id, status: refund.status };
}

// src/services/order.service.ts - createOrder metodu
async createOrder(userId: string, shippingAddress: string) {
  const cartItems = await this.cartService.getCart(userId);
  if (cartItems.length === 0) throw new AppError('Sepetiniz boş', 400);

  // Transaction ile atomik sipariş oluşturma
  const order = await prisma.$transaction(async (tx) => {
    // 1. Stok kontrolü ve kilitleme (SELECT FOR UPDATE)
    for (const item of cartItems) {
      const product = await tx.product.findUnique({
        where: { id: item.productId },
      });

      if (!product) {
        throw new AppError(`Ürün bulunamadı: ${item.name}`, 404);
      }

      if (product.stock < item.quantity) {
        throw new AppError(
          `${item.name} için yeterli stok yok (Stok: ${product.stock}, İstenen: ${item.quantity})`,
          400
        );
      }
    }

    // 2. Toplam hesapla
    const totalAmount = cartItems.reduce(
      (sum, item) => sum + item.price * item.quantity, 0
    );

    // 3. Sipariş oluştur
    const newOrder = await tx.order.create({
      data: {
        userId,
        totalAmount,
        shippingAddress,
        status: 'PENDING',
        items: {
          create: cartItems.map((item) => ({
            productId: item.productId,
            quantity: item.quantity,
            unitPrice: item.price,
          })),
        },
      },
      include: { items: { include: { product: true } } },
    });

    return newOrder;
  }, {
    isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
  });

  return order;
}

