// src/services/stock.service.ts
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();
const LOW_STOCK_THRESHOLD = 5;

export class StockService {
  async checkLowStock() {
    const lowStockProducts = await prisma.product.findMany({
      where: {
        isActive: true,
        stock: { lte: LOW_STOCK_THRESHOLD },
      },
      select: { id: true, name: true, stock: true, slug: true },
      orderBy: { stock: 'asc' },
    });

    return lowStockProducts;
  }

  async getStockReport() {
    const [totalProducts, outOfStock, lowStock, totalValue] = await Promise.all([
      prisma.product.count({ where: { isActive: true } }),
      prisma.product.count({ where: { isActive: true, stock: 0 } }),
      prisma.product.count({ where: { isActive: true, stock: { lte: LOW_STOCK_THRESHOLD, gt: 0 } } }),
      prisma.product.aggregate({
        where: { isActive: true },
        _sum: { price: true },
      }),
    ]);

    return {
      totalProducts,
      outOfStock,
      lowStock,
      inStock: totalProducts - outOfStock,
    };
  }
}

// src/services/fraud.service.ts
import axios from 'axios';

const FRAUD_SERVICE_URL = process.env.FRAUD_SERVICE_URL || 'http://localhost:5000';

interface FraudResult {
  fraud_score: number;
  is_suspicious: boolean;
  risk_level: 'low' | 'medium' | 'high';
}

export class FraudService {
  async analyzeOrder(orderData: {
    orderAmount: number;
    itemsCount: number;
    isNewCustomer: boolean;
    shippingBillingMatch: boolean;
    previousOrders: number;
  }): Promise<FraudResult> {
    try {
      const { data } = await axios.post(`${FRAUD_SERVICE_URL}/predict`, {
        order_amount: orderData.orderAmount,
        items_count: orderData.itemsCount,
        hour_of_day: new Date().getHours(),
        is_new_customer: orderData.isNewCustomer ? 1 : 0,
        shipping_billing_match: orderData.shippingBillingMatch ? 1 : 0,
        previous_orders: orderData.previousOrders,
      });

      return data;
    } catch (error) {
      console.error('Fraud service error:', error);
      // Fraud servisi çöktüğünde siparişi engelleme
      return { fraud_score: 0, is_suspicious: false, risk_level: 'low' };
    }
  }
}

